        'ms365_open_intune_import' => 'Import',
        'zabbix_blurb' => 'Masalah pemantauan membuka insiden dengan sendirinya, kejadian berulang ditambah padanya, dan pemulihan menyelesaikannya.',
        'zabbix_intro' => 'Apabila Zabbix menemui masalah - cakera hampir penuh, pelayan tidak menjawab - ia menimbulkan insiden di sini, dipautkan kepada pelayan itu dalam CMDB. Jika ia melaporkan masalah yang sama lagi, ia dimasukkan ke tiket yang sama. Apabila masalah hilang, tiket diselesaikan.',
        'zabbix_direction' => 'Zabbix menghubungi FreeITSM - FreeITSM tidak pernah bersambung ke Zabbix, jadi ia tidak memerlukan alamat Zabbix atau kata laluan Zabbix. Semua yang diperlukan Zabbix ada di bawah.',
        'zabbix_not_ready' => 'Jalankan Sistem → Pengesahan Pangkalan Data dahulu: ia mencipta jadual tempat integrasi ini menyimpan log peristiwanya.',
        'zabbix_connect' => 'Sambungkan Zabbix',
        'zabbix_connect_body' => 'Zabbix menghantar setiap makluman ke alamat di bawah bersama token rahsia. Dalam Zabbix, pergi ke Alerts → Media types → Create media type, pilih Webhook, namakan FreeITSM, tampal parameter dan skrip di bawah, kemudian tambahkannya kepada pengguna dan kepada tindakan di bawah Alerts → Actions → Trigger actions. Tandakan "Recovery operations" dalam tindakan itu, atau tiket tidak akan pernah diselesaikan.',
        'zabbix_endpoint' => 'Alamat FreeITSM (berikan ini kepada Zabbix)',
        'zabbix_import' => 'Paling cepat: import ke dalam Zabbix',
        'zabbix_import_body' => 'Muat turun media type dengan semua yang telah diisi - alamat di atas, token anda, skrip dan tiga templat mesej - kemudian dalam Zabbix pergi ke Alerts → Media types → Import dan pilih fail itu. Selepas itu, berikan kepada pengguna dan tambah tindakan (langkah 4 dalam panduan).',
        'zabbix_import_download' => 'Muat turun untuk import Zabbix',
        'zabbix_import_needs_token' => 'Buat token dahulu - fail itu membawanya.',
        'zabbix_by_hand' => 'Atau sediakan secara manual',
        'zabbix_token' => 'Token',
        'zabbix_token_none' => 'Belum ada token - buat satu untuk menghidupkan integrasi.',
        'zabbix_token_make' => 'Buat token',
        'zabbix_token_rotate' => 'Token baharu',
        'zabbix_rotate_confirm' => 'Buat token baharu? Yang lama berhenti berfungsi serta-merta, jadi Zabbix akan gagal sehingga anda menampal yang baharu ke dalam media type nya.',
        'zabbix_params' => 'Parameter media type',
        'zabbix_params_hint' => 'Padam parameter yang diisi Zabbix untuk webhook baharu (URL, HTTPProxy, To, Subject, Message) - ia milik skrip contohnya, bukan skrip ini. Kemudian tambah setiap baris di sini sebagai parameter: nama di sebelah kiri, nilai di sebelah kanan. http_proxy dibiarkan kosong melainkan pelayan Zabbix anda hanya boleh sampai ke FreeITSM melalui proksi. Nilai dalam kurungan kerawang ialah makro Zabbix - biarkan seperti sedia ada. Baris url memberi setiap tiket pautan kembali ke masalah dalam Zabbix; ia memerlukan makro {$ZABBIX.URL} ditetapkan kepada alamat web Zabbix anda (Zabbix: Administration → Macros). Tanpanya, tiket hanya tidak mempunyai pautan.',
        'zabbix_script' => 'Skrip media type',
        'zabbix_copy' => 'Salin',
        'zabbix_copied' => 'Disalin.',
        'zabbix_reach_hint' => 'Tempat Zabbix akan menghantar makluman. Ia bermula sebagai URL asas awam anda; jika Zabbix berada pada pelayan atau rangkaian yang sama, laluannya ke FreeITSM mungkin berbeza - untuk Zabbix dalam Docker pada mesin ini, http://host.docker.internal/ dan selebihnya laluan itu. Ubahnya di sini dan parameter serta muat turun akan mengikutinya.',
        'zabbix_tickets' => 'Insiden yang ditimbulkannya',
