        'zabbix_recovery' => 'pemulihan',
        'zabbix_test' => 'Cuba',
        'zabbix_test_body' => 'Menghantar masalah ujian melalui integrasi, tepat seperti makluman sebenar daripada Zabbix dikendalikan: insiden ditimbulkan dengan tetapan anda, dan anda kemudian boleh menghantar pemulihannya untuk melihatnya diselesaikan. Insiden ujian kekal, bertajuk sebagai ujian, supaya anda dapat melihat rupa insiden sebenar - tutupnya seperti tiket lain.',
        'zabbix_test_limit' => 'Ini menguji bahagian FreeITSM. Sama ada pelayan Zabbix anda boleh sampai ke FreeITSM ialah bahagian yang lain: uji itu dengan butang Test pada media type dalam Zabbix.',
