        'msteams_blurb' => 'Makluman meja perkhidmatan sebagai kad dalam saluran Teams anda - tiket segera, pelanggaran SLA, tiket bagi setiap pasukan - dengan butang terus ke tiket.',
        'msteams_intro' => 'Siarkan makluman meja perkhidmatan ke saluran Microsoft Teams sebagai kad, masing-masing dengan butang Buka dalam FreeITSM. Tandakan apa yang patut diketahui oleh setiap saluran: tiket segera, amaran dan pelanggaran SLA, tiket bagi pasukannya, insiden halaman status, kelulusan yang menunggu.',
