        'msteams_bot_h' => 'Bot sembang Teams',
        'msteams_bot_body' => 'Halaman ini hanya menyiarkan makluman. Untuk orang bersembang dengan meja perkhidmatan dalam Teams - setiap perbualan menjadi tiket - sediakan bot Teams di bawah Tiket → Tetapan → Pemesejan.',
        'msteams_bot_count' => '{n} saluran bot Teams disediakan.',
