        'msteams_how_h' => 'Dapatkan alamat webhook saluran',
        'msteams_how_body' => 'Dalam Teams, buka saluran, klik … di sebelah namanya, kemudian Workflows. Pilih "Post to a channel when a webhook request is received", ikuti langkahnya, dan salin alamat yang diberikan pada akhirnya. Tampalkannya ke dalam saluran di bawah. Alamat ini berfungsi seperti kata laluan: sesiapa yang memilikinya boleh menyiarkan ke saluran itu, jadi ia disimpan dalam bentuk disulitkan dan tidak dipaparkan lagi.',
