        'threecx_blurb' => 'Lihat siapa yang menelefon sebelum anda menjawab, simpan setiap panggilan pada tiket pemanggil, dan dail nombor dengan satu klik.',
        'threecx_intro' => 'Apabila panggilan berdering, 3CX bertanya FreeITSM siapa pemilik nombor itu dan memaparkan nama pemanggil - serta membuka tiketnya untuk penganalisis. Apabila panggilan tamat, ia dicatat pada tiket itu, ditulis oleh penganalisis yang menjawabnya. Nombor telefon pada tiket dan orang juga boleh didail keluar melalui 3CX.',
        'threecx_direction' => '3CX menghubungi FreeITSM - FreeITSM tidak pernah bersambung ke 3CX, jadi ia tidak memerlukan alamat sistem telefon anda atau kata laluan 3CX. Semua yang diperlukan 3CX ada dalam templat di bawah.',
        'threecx_not_ready' => 'Jalankan Sistem → Pengesahan Pangkalan Data dahulu: ia mencipta jadual tempat integrasi ini menyimpan log panggilannya.',
        'threecx_connect' => 'Sambungkan 3CX',
        'threecx_connect_body' => '3CX bersambung ke FreeITSM melalui templat CRM. Buat token, muat turun templat, dan muat naik di 3CX Admin Console di bawah Integrations → CRM. 3CX mesti dapat sampai ke alamat di bawah.',
        'threecx_endpoint' => 'Alamat FreeITSM, seperti yang akan dicapai oleh 3CX',
        'threecx_reach_hint' => 'Ia bermula sebagai URL asas awam anda. 3CX selalunya berada dalam awan, jadi ini mesti alamat yang boleh dicapai dari internet. Ubahnya di sini dan muat turun akan mengikutinya.',
        'threecx_token' => 'Token',
        'threecx_token_none' => 'Belum ada token - buat satu untuk menghidupkan integrasi.',
        'threecx_token_make' => 'Buat',
        'threecx_token_rotate' => 'Ganti',
        'threecx_rotate_confirm' => 'Buat token baharu? 3CX tidak dapat sampai ke FreeITSM sehingga anda memuat naik templat sekali lagi (atau menampal token baharu ke dalamnya).',
        'threecx_copy' => 'Salin',
        'threecx_copied' => 'Disalin.',
        'threecx_download' => 'Muat turun',
        'threecx_download_body' => 'Templat, sedia untuk dimuat naik: alamat, token ini, carian pemanggil dan laporan panggilan. Ia mengandungi token, jadi simpan fail itu untuk diri anda sendiri.',
        'threecx_download_needs_token' => 'Buat token dahulu - templat membawanya.',
        'threecx_calls_h' => 'Panggilan pada tiket',
        'threecx_rule' => 'Tiket mana yang menerima panggilan',
        'threecx_rule_latest' => 'Tiket terbuka pemanggil yang paling baru dikemas kini',
        'threecx_rule_only_one' => 'Hanya apabila pemanggil mempunyai tepat satu tiket terbuka',
        'threecx_rule_log_only' => 'Tiada - panggilan hanya disenaraikan di bawah',
        'threecx_rule_hint' => 'Tiket yang dibuka 3CX untuk penganalisis apabila panggilan berdering mengikut pilihan yang sama.',
        'threecx_create' => 'Buka tiket baharu untuk panggilan daripada seseorang yang tiada tiket terbuka',
        'threecx_create_unknown' => 'Juga untuk nombor yang tiada sesiapa dalam FreeITSM memilikinya',
        'threecx_create_hint' => 'Hanya untuk panggilan masuk (dijawab atau terlepas). Penganalisis yang menjawab panggilan ditugaskan. Pemanggil yang tidak dikenali difailkan sebagai "Pemanggil" dan nombornya, sedia untuk dipautkan kepada orang yang betul.',
        'threecx_fallback' => 'Tulis nota sebagai, apabila pengguna 3CX bukan penganalisis',
        'threecx_fallback_hint' => 'Nota ditulis oleh penganalisis yang e-melnya sepadan dengan pengguna 3CX yang menjawab panggilan. Apabila tiada yang sepadan - penyambut tetamu, telefon bersama - ia ditulis oleh penganalisis ini sebaliknya, dengan menyatakan siapa yang menjawabnya. Jika tiada sesiapa dipilih, panggilan itu hanya disenaraikan di bawah.',
        'threecx_nobody' => 'Tiada sesiapa',
        'threecx_company' => 'Syarikat untuk tiket daripada nombor yang tidak dikenali',
        'threecx_company_hint' => 'Tiket pemanggil yang dikenali masuk ke syarikat mereka sendiri.',
        'threecx_team' => 'Pasukan untuk tiket baharu',
        'threecx_origin' => 'Asal untuk tiket baharu',
        'threecx_none' => 'Tiada',
        'threecx_dial_h' => 'Klik untuk memanggil',
        'threecx_dial_body' => 'Nombor telefon pada tiket, pada Tiket → Pengguna dan pada Orang mendapat butang Panggil yang mendail melalui telefon anda. Ia dibuka pada komputer penganalisis sendiri, tempat mereka sudah log masuk ke 3CX, jadi FreeITSM tidak memerlukan sambungan (extension) mereka.',
        'threecx_dial' => 'Alamat dail',
        'threecx_dial_hint' => 'Letakkan {number} di tempat nombor diletakkan. Untuk klien web 3CX: https://your-pbx.3cx.com/webclient/#/call?phone={number}. Untuk aplikasi desktop 3CX (atau mana-mana softphone): tel:{number}. Biarkan kosong untuk mematikan butang Panggil.',
        'threecx_saved' => 'Disimpan.',
        'threecx_try' => 'Cuba panggilan',
        'threecx_try_body' => 'Lihat apa yang akan dilakukan oleh panggilan dengan tetapan ini - siapa pemanggilnya, tiket mana yang akan menerimanya dan siapa yang akan menulis nota. Tiada apa-apa ditulis: ia keputusan yang sama seperti panggilan sebenar, cuma diterangkan.',
