        'not_configured' => 'Belum disediakan',
        'tika_blurb' => 'Baca teks di dalam PDF, fail Office lama dan dokumen yang diimbas supaya ia boleh dicari.',
        'tika_intro' => 'Mengarahkan FreeITSM kepada perkhidmatan pembacaan dokumen. Fail Word, Excel, PowerPoint dan teks biasa sudah boleh dicari tanpa ini; Tika menambah format yang tidak dapat dibaca sendiri oleh FreeITSM.',
        'tika_security_title' => 'Jauhkan daripada rangkaian',
        'tika_security_body' => 'Tika tiada kata laluan dan tiada pengesahan dalam apa jua bentuk: apa sahaja yang boleh mencapainya akan membaca apa sahaja fail yang dihantar kepadanya. Jalankannya supaya hanya server ini boleh berkomunikasi dengannya — terikat kepada 127.0.0.1, atau pada rangkaian bekas peribadi — dan jangan sekali-kali dedahkan portnya kepada internet.',
        'tika_connection' => 'Sambungan',
        'tika_url_label' => 'Alamat',
        'tika_url_hint' => 'Contohnya http://127.0.0.1:9998. Biarkan ini kosong untuk mematikan pembacaan dokumen; PDF hanya akan disenaraikan sebagai tidak boleh dibaca.',
        'tika_timeout_label' => 'Had masa (saat)',
        'tika_timeout_hint' => 'Berapa lama untuk menunggu satu dokumen. Halaman yang diimbas mengambil masa jauh lebih lama daripada teks biasa.',
