        'tika_scanned' => 'Dokumen yang diimbas dan gambar teks, melalui pengecaman aksara',
        'tika_running' => 'Menjalankan satu',
        'tika_running_body' => 'FreeITSM tidak memasang atau menguruskan Tika. Jalankannya sendiri, di mana sahaja yang sesuai untuk anda, dan letakkan alamatnya di atas. Dengan Docker itu hanya satu arahan:',
        'tika_image_note' => 'Gunakan imej -full. Yang lebih kecil tiada pengecaman aksara, jadi dokumen yang diimbas akan kembali kosong.',
        'slack_workspaces' => 'Ruang kerja Slack',
        'slack_workspaces_desc' => 'Setiap satu ialah aplikasi Slack yang anda pasang dalam ruang kerja anda sendiri. FreeITSM tidak pernah melihat trafik Slack anda — aplikasi itu bercakap terus dengan pelayan ini.',
        'slack_col_channel' => 'Dipantau',
        'slack_any_channel' => 'Mana-mana saluran yang menjemputnya',
        'slack_empty' => 'Belum ada ruang kerja Slack. Tambah satu, kemudian dapatkan aplikasinya daripada Slack.',
        'slack_needs_setup' => 'Perlu disediakan',
        'slack_add_title' => 'Tambah ruang kerja Slack',
        'slack_edit_title' => 'Edit ruang kerja Slack',
        'slack_name_hint' => 'Hanya digunakan dalam senarai ini, dan sebagai nama aplikasi Slack yang anda cipta.',
        'slack_name_required' => 'Berikan nama untuk ruang kerja ini.',
        'slack_unchanged' => 'Tidak berubah — biarkan kosong untuk mengekalkannya',
        'slack_bot_token' => 'Token OAuth pengguna bot',
        'slack_bot_token_hint' => 'Daripada aplikasi Slack anda, di bawah OAuth &amp; Permissions. Bermula dengan xoxb-. Anda mendapatnya selepas memasang aplikasi, jadi biarkan kosong pada simpanan pertama.',
        'slack_signing_secret' => 'Rahsia tandatangan',
        'slack_signing_secret_hint' => 'Daripada aplikasi Slack anda, di bawah Basic Information. Beginilah cara FreeITSM membuktikan mesej itu benar-benar daripada Slack, jadi tiada apa yang diterima sehingga ia ditetapkan.',
        'slack_watch_channel' => 'Pantau saluran ini sahaja',
        'slack_watch_channel_hint' => 'ID saluran Slack seperti C08ABCDEF. Biarkan kosong untuk menaikkan tiket daripada setiap saluran yang menjemput aplikasi itu — yang pada saluran sibuk bermaksud satu tiket setiap mesej, jadi kebanyakan orang menamakan satu saluran bantuan di sini.',
        'slack_company_shared' => 'Dikongsi — putuskan mengikut penghantar',
        'slack_company_hint' => 'Pautkan ruang kerja ini kepada satu syarikat, atau biarkan dikongsi dan biar penghantar yang menentukan.',
        'slack_delete_confirm' => 'Padam ruang kerja Slack "{name}"? Tiket yang sudah dinaikkan daripadanya mengekalkan sejarahnya; hanya mesej baharu berhenti tiba.',
        'slack_diag_title' => 'Semakan kesihatan Slack',
        'slack_diag_desc' => 'Menyemak segala yang boleh salah secara senyap — bukan sekadar sama ada token berfungsi. Setiap keputusan menyatakan apa yang perlu dilakukan.',
        'slack_diag_running' => 'Menyemak — ini bercakap dengan Slack dan dengan alamat awam anda sendiri, jadi beri ia beberapa saat…',
        'slack_diag_rerun' => 'Jalankan semula',
        'slack_diag_all_ok' => 'Semuanya baik. Mesej yang dihantar dalam saluran Slack yang dipantau akan menjadi tiket, dan balasan akan kembali ke bebenang itu.',
        'slack_diag_some_warn' => 'Berfungsi, dengan sesuatu yang perlu diketahui. Tiada apa di bawah menghalang tiket daripada tiba, tetapi berbaloi dibaca.',
        'slack_diag_some_fail' => 'Ada sesuatu yang tidak kena dan mesej tidak akan tiba. Semakan yang gagal di bawah menyatakan apa yang perlu dilakukan.',
        'slack_app_title' => 'Aplikasi Slack',
        'slack_copy_manifest' => 'Salin manifes',
        'slack_scopes_heading' => 'Apa yang aplikasi ini dibenarkan buat',
        'slack_scopes_desc' => 'Pentadbir Slack anda akan melihat senarai ini semasa meluluskan aplikasi. Tiada apa di sini membenarkannya mencipta saluran, menjemput orang atau menyiarkan di mana-mana yang ia belum dijemput.',
        'slack_step1' => 'Dalam Slack, pergi ke <strong>api.slack.com/apps</strong> dan pilih <strong>Create New App → From a manifest</strong>. Pilih ruang kerja tempat anda mahukan meja perkhidmatan ini.',
        'slack_step2' => 'Tampal manifes ini. Ia menetapkan nama, kebenaran dan alamat tempat Slack menghantar mesej, jadi tiada apa perlu ditanda secara manual.',
        'slack_step3' => 'Klik <strong>Install to Workspace</strong> dan luluskannya. Kemudian salin <strong>Bot User OAuth Token</strong> dan <strong>Signing Secret</strong> kembali ke borang Edit di sini — Slack tidak akan menunjukkan token itu lagi. <strong>Jika Slack menunjukkan sepanduk kuning &ldquo;Reinstall to Workspace&rdquo;, klik itu dahulu</strong> — jika tidak, token itu kehilangan kebanyakan kebenarannya dan tiket tiba tanpa nama penghantar.',
        'slack_step4' => 'Semak URL permintaan di bawah sepadan dengan apa yang ditunjukkan Slack di bawah <strong>Event Subscriptions</strong>. Slack mengesahkannya sebaik sahaja anda menyimpan aplikasi, jadi pelayan ini perlu boleh dicapai daripada internet.',
        'slack_step5' => 'Dalam Slack, jemput aplikasi ke saluran yang anda mahu ia pantau: <strong>/invite @AplikasiAnda</strong>. Ia tidak dapat membaca saluran yang ia bukan ahlinya.',
    ],
