        'status_restart_title' => 'Mulakan semula kontena untuk menyelesaikan',
        'status_restart_body' => 'Sijil untuk {host} sudah sedia, tetapi kontena masih berjalan tanpanya. Jalankan {cmd} dalam folder yang mengandungi docker-compose.yml anda.',
        'form_heading' => 'Sijil',
        'browsing_at' => 'Anda mencapai FreeITSM di {address}.',
        'host_label' => 'Nama yang akan ditaip orang',
        'host_help' => 'Contohnya freeitsm.internal. Nama yang berakhir dengan .internal selamat digunakan di dalam rangkaian syarikat. Elakkan .local, yang dikhaskan oleh sesetengah PC untuk kegunaan lain.',
        'ip_label' => 'Alamat IP pelayan',
        'ip_help' => 'Alamat mesin yang menjalankan Docker, seperti yang dilihat oleh PC. Diisi daripada bar alamat anda apabila anda mencapai halaman ini melalui IP. Pilihan, tetapi ia membolehkan HTTPS berfungsi melalui IP juga.',
        'generate' => 'Jana',
