        'confirm_new_ca' => 'Menukar nama atau IP akan membuat sijil pihak berkuasa yang baharu. Setiap PC yang mempercayai yang lama perlu memasang yang baharu. Teruskan?',
        'err_invalid_host' => 'Itu bukan nama yang sah. Gunakan huruf, nombor, tanda sempang dan titik sahaja, contohnya freeitsm.internal.',
        'err_invalid_ip' => 'Itu bukan alamat IP yang sah.',
        'err_not_persisted' => 'Buat perubahan Docker di bahagian atas halaman ini dahulu.',
        'err_generic' => 'Sijil tidak dapat dibuat: {error}',
        'steps_heading' => 'Apa yang perlu dilakukan seterusnya',
        'step_dns_title' => 'Halakan nama itu ke pelayan',
        'step_dns_body' => 'PC perlu tahu bahawa {host} bermaksud {ip}. Cara terbaik ialah rekod DNS pada pelayan DNS rangkaian anda (pada domain Windows, dalam DNS Manager; pada rangkaian kecil, selalunya dalam penghala):',
        'step_dns_record' => 'Jenis A, nama {host}, alamat {ip}',
