        'step_dns_no_ip' => 'Isi alamat IP pelayan di atas untuk melihat rekod tepat yang perlu dibuat.',
        'step_ca_title' => 'Pasang sijil pihak berkuasa pada setiap PC',
        'step_ca_body' => 'Ini memberitahu PC supaya mempercayai sijil itu. Ia hanya perlu dilakukan sekali bagi setiap PC, dan sekali lagi hanya jika anda menukar nama atau IP.',
        'download' => 'Muat turun',
        'step_ca_windows' => 'Windows: klik dua kali fail itu, pilih Install Certificate, pilih Local Machine, kemudian Place all certificates in the following store, dan pilih Trusted Root Certification Authorities.',
        'step_ca_gpo' => 'Banyak PC Windows dalam domain: import fail itu sekali dalam Group Policy, di bawah Computer Configuration → Policies → Windows Settings → Security Settings → Public Key Policies → Trusted Root Certification Authorities. Intune boleh menolaknya sebagai profil sijil Trusted.',
        'step_ca_mac' => 'Mac: klik dua kali fail itu untuk menambahnya ke Keychain Access, buka di sana, dan tetapkan When using this certificate kepada Always Trust.',
        'step_ca_firefox' => 'Firefox pada Windows menggunakan sijil Windows secara automatik. Jika ia masih memberi amaran, tetapkan security.enterprise_roots.enabled kepada true dalam about:config.',
        'step_ca_safe' => 'Pihak berkuasa ini hanya boleh menjamin {host}, tiada yang lain, jadi memasangnya tidak membolehkannya menyamar sebagai mana-mana laman web lain.',
        'step_restart_title' => 'Mulakan semula kontena',
        'step_restart_body' => 'Jalankan {cmd} dalam folder yang mengandungi docker-compose.yml anda.',
        'step_restart_done' => 'Selesai: kontena menggunakan sijil ini.',
        'step_open_title' => 'Buka FreeITSM melalui HTTPS',
        'step_open_body' => 'Pergi ke {url}. Jika ia tidak dimuatkan, semak bahawa docker-compose.yml anda menerbitkan port 443 (fail standard memetakannya ke 8443). Jika anda mengubahnya, gunakan port anda.',
        'proxy_heading' => 'Di belakang proksi songsang',
        'proxy_intro' => 'Jika proksi songsang, pengimbang beban atau Cloudflare Tunnel berada di hadapan FreeITSM, setiap permintaan sampai ke FreeITSM daripada proksi. Melainkan anda memberitahu FreeITSM alamat mana ialah proksi, ia merekodkan alamat proksi untuk semua orang: dalam Reporting → Logs, dalam jejak audit, dan apabila kunci API menyemak alamat yang dibenarkannya.',
        'proxy_off_title' => 'Mati',
        'proxy_off_body' => 'FreeITSM merekodkan alamat tempat setiap sambungan datang. Itu betul apabila orang menyambung terus ke FreeITSM, dan salah di belakang proksi - gunakan Uji di bawah untuk melihat yang mana satu anda ada.',
        'proxy_on_title' => 'Hidup',
        'proxy_on_body' => 'Alamat sebenar diambil daripada pengepala {header}, tetapi hanya pada permintaan yang datang daripada {list}.',
        'proxy_refused_title' => 'Ditetapkan, tetapi tidak berkuat kuasa',
        'proxy_refused_body' => 'TRUSTED_PROXIES ditetapkan kepada {list}, tetapi ia ditolak apabila kontena bermula, jadi FreeITSM merekodkan alamat tempat setiap sambungan datang. Jalankan {cmd} untuk melihat sebabnya.',
        'proxy_wide_title' => 'Amaran: tetapan ini terlalu luas',
        'proxy_wide_body' => '{ranges} meliputi lebih daripada satu proksi. Setiap mesin di dalamnya boleh mendakwa sebagai mana-mana alamat yang disukainya. Tukar TRUSTED_PROXIES kepada alamat proksi itu sendiri dan mulakan semula kontena.',
        'proxy_danger_title' => 'Apa yang dilakukan oleh tetapan yang salah - baca ini sebelum anda mengubahnya',
        'proxy_danger_wide' => 'Terlalu luas - kesilapan yang berbahaya. FreeITSM mempercayai alamat dalam pengepala proksi hanya pada permintaan daripada alamat yang anda senaraikan, kerana sesiapa sahaja boleh menulis pengepala itu. Senaraikan julat seperti {example} atau seluruh rangkaian Docker, dan mana-mana mesin di dalamnya boleh mendakwa sebagai mana-mana alamat: ia boleh meletakkan alamat palsu dalam log log masuk dan jejak audit, dan melepasi kunci API yang hanya membenarkan alamat tertentu. Senaraikan hanya alamat proksi itu sendiri.',
        'proxy_danger_missing' => 'Tidak ditetapkan, apabila ada proksi. Tiada apa-apa rosak, tetapi setiap log masuk dan setiap perubahan direkodkan daripada alamat proksi, jadi log tidak dapat membezakan orang - dan alamat yang dibenarkan bagi kunci API hanya boleh menamakan proksi, yang membenarkan sesiapa sahaja yang melaluinya.',
        'proxy_danger_wrong' => 'Alamat yang salah. Pengepala diabaikan, jadi anda kembali kepada semua orang direkodkan sebagai proksi. Uji menunjukkan ini dengan segera.',
        'proxy_how' => 'Ini ditetapkan dalam docker-compose.yml, bukan pada halaman ini, dan berkuat kuasa apabila kontena dimulakan semula (docker compose up -d):',
        'proxy_how_cf' => 'Untuk Cloudflare Tunnel, tetapkan juga {setting}. Beberapa proksi: asingkan dengan ruang.',
        'proxy_test_heading' => 'Uji.',
        'proxy_test_intro' => 'Menunjukkan alamat yang direkodkan oleh FreeITSM untuk anda sebentar tadi, dan maksudnya. Ia tidak mengubah apa-apa.',
        'proxy_test' => 'Uji',
        'proxy_testing' => 'Menguji...',
        'proxy_test_failed' => 'Ujian tidak dapat dijalankan.',
        'proxy_recorded' => 'FreeITSM merekodkan alamat anda sebagai',
        'verdict_direct' => 'Anda menyambung terus ke FreeITSM - tiada pengepala proksi tiba - jadi tiada apa-apa untuk ditetapkan. Jika anda tahu ada proksi di hadapan, ia tidak menambah pengepala: semak tetapannya.',
        'verdict_off_proxy' => 'Proksi berada di hadapan FreeITSM (permintaan ini membawa {headers}), dan FreeITSM merekodkan alamat proksi, {ip}, untuk semua orang. Untuk merekodkan alamat sebenar, tambah ini pada persekitaran aplikasi dalam docker-compose.yml:',
        'proxy_suggest_then' => 'Itulah alamat proksi seperti yang dilihat oleh FreeITSM - senaraikan sahaja ia, tiada yang lebih luas. Kemudian jalankan docker compose up -d dan uji sekali lagi.',
        'verdict_working' => 'Berfungsi: alamat ini datang daripada pengepala proksi. Semak ia benar-benar alamat komputer anda - pada Windows, ipconfig menunjukkannya; dari luar rangkaian anda, alamat awam anda. Jika ia menunjukkan alamat proksi atau 127.0.0.1, ada sesuatu yang salah.',
        'verdict_too_wide' => 'Tidak selamat: alamat anda sendiri, {ip}, berada dalam julat yang dipercayai FreeITSM sebagai proksi, jadi FreeITSM tidak dapat membezakan anda daripada proksi - dan sesiapa sahaja dalam julat itu boleh mendakwa sebagai mana-mana alamat. Tukar TRUSTED_PROXIES kepada alamat proksi itu sendiri dan mulakan semula kontena.',
        'verdict_still_proxy' => 'Tidak berfungsi: alamat yang direkodkan ialah proksi itu sendiri, jadi proksi tidak menghantar pengepala {header}. Jadikan proksi menambah {header}, atau tetapkan TRUSTED_PROXY_HEADER kepada pengepala yang dihantarnya.',
        'verdict_refused' => 'Tetapan tidak berkuat kuasa (lihat di atas), jadi FreeITSM merekodkan alamat tempat setiap sambungan datang. Betulkan tetapan dahulu, kemudian uji sekali lagi.',
        'proxy_headers_seen' => 'Pengepala proksi pada permintaan ini:',
        'proxy_headers_none' => 'Tiada pengepala proksi pada permintaan ini.',
