        'people_desc_caldav' => 'Setiap penganalisis log masuk ke pelayan CalDAV dan memilih kalendar mereka sendiri di bawah Keutamaan. Pentadbir tidak dapat memilihnya untuk mereka, kerana hanya penganalisis itu yang mempunyai kata laluan yang boleh mencapainya.',
        'no_account' => 'Belum log masuk',
        'switch_title' => 'Tukar tempat sambungan ini menulis?',
        'switch_confirm' => 'Ini menarik balik {mapped} acara yang telah diletakkan oleh sambungan ini dalam kalendar penganalisis, dan mematikan penyegerakan kalendar untuk {pushing} penganalisis yang menggunakannya, supaya masing-masing boleh menyediakannya semula. Penganalisis pada sambungan lain, dan pautan langganan, tidak terjejas.',
        'switch_ok' => 'Tukar',
        'switch_done' => 'Disimpan. Penyegerakan kalendar telah ditetapkan semula untuk penganalisis pada sambungan ini.',
        'perm_title' => 'Sebelum ini berfungsi',
        'perm_body' => 'Pendaftaran aplikasi memerlukan <strong>Calendars.ReadWrite</strong> sebagai kebenaran <strong>Application</strong> (bukan Delegated — kedua-duanya senarai berasingan dalam Azure), dengan persetujuan pentadbir diberikan. Ambil perhatian bahawa kebenaran ini membenarkan FreeITSM menulis ke <strong>setiap peti mel dalam penyewa</strong>. Jika itu lebih daripada yang anda mahu berikan, hadkan skop aplikasi kepada kumpulan keselamatan berupaya mel bagi penganalisis anda menggunakan Application Access Policy dalam Exchange Online.',
        'name' => 'Nama',
        'source_mailbox' => 'Pinjam kelayakan daripada peti mel',
        'source_own' => 'Masukkan kelayakan',
        'mailbox' => 'Peti mel',
        'no_mailboxes' => 'Tiada peti mel Microsoft pada sistem ini yang mempunyai kelayakan Azure untuk dipinjam, jadi masukkannya di bawah. Ini adalah normal jika kalendar penganalisis anda berada dalam penyewa yang berbeza daripada peti mel intake anda, atau jika intake anda bukan Microsoft langsung.',
        'tenant_id' => 'ID Direktori (penyewa)',
        'client_id' => 'ID Aplikasi (klien)',
        'client_secret' => 'Rahsia klien',
        'secret_note' => 'Rahsia disimpan secara disulitkan dan tidak akan ditunjukkan lagi. Biarkan kosong semasa menyunting untuk mengekalkan yang sudah disimpan.',
        'test' => 'Uji',
