        'test_failed' => 'Tidak dapat bersambung.',
        'test_failed_hint' => 'Semak bahawa rahsia klien belum tamat tempoh, dan bahawa Calendars.ReadWrite disenaraikan di bawah kebenaran Application dengan persetujuan pentadbir diberikan.',
        'probe_ok' => '{addr} mempunyai kalendar yang FreeITSM boleh tulis ke.',
        'probe_bad' => 'Tiada kalendar ditemui untuk {addr}. Semak bahawa alamat itu ialah peti mel sebenar dalam penyewa ini — alamat e-mel FreeITSM penganalisis tidak selalunya alamat peti mel mereka.',
        'conn_delete_confirm' => 'Padam "{name}"?',
        'conn_delete_title' => 'Padam sambungan ini?',
        'conn_delete_used' => 'FreeITSM menarik balik {mapped} acara yang telah diletakkan oleh sambungan ini dalam kalendar penganalisis, dan mematikan penyegerakan kalendar untuk {pushing} penganalisis yang menggunakannya. Penganalisis pada sambungan lain tidak terjejas.',
        'conn_deleted' => 'Sambungan dipadam',
        'people_heading' => 'Peti mel mana setiap penganalisis menyegerak kepada',
        'people_desc' => 'Secara lalai FreeITSM menggunakan alamat e-mel pada akaun penganalisis, yang selalunya bukan peti mel mereka &mdash; akaun tempatan, atau import direktori yang berdasarkan sesuatu yang lain. Tulis ganti di sini. Penganalisis memilih <em>sama ada</em> kerja mereka disegerakkan; hanya pentadbir yang memilih <em>ke mana</em> ia pergi.',
        'col_analyst' => 'Penganalisis',
