        'tasks_both' => 'Tugasan: kedua-duanya',
        'tasks_note' => 'Penganalisis ini telah memilih untuk menyertakan tugasan mereka. Mereka memilih ini sendiri di bawah Keutamaan; ia tidak boleh ditetapkan untuk mereka di sini.',
        'saved_unverified' => 'Disimpan. Alamat tidak dapat disemak kerana sambungan tidak berfungsi — ujinya di atas.',
        'inbound_heading' => 'Perubahan dibuat dalam kalendar',
        'inbound_desc' => 'Alihkan salah satu temu janji ini dalam Outlook dan tiket akan mengikut. Ini memerlukan tugas <code>cron/calendar_sync_pull.php</code> berjalan &mdash; setiap 5 minit adalah munasabah. Tanpanya penyegerakan adalah sehala, yang mana itulah cara ia berfungsi pada hari ini.',
        'accept_deletes' => 'Memadam temu janji membatalkan jadual tiket',
        'notify_url' => 'URL Pemberitahuan (pilihan)',
        'notify_url_note' => 'Biarkan kosong untuk bergantung pada semakan berjadual sahaja, yang mana itu memadai &mdash; perubahan akan tiba dalam beberapa minit. Isikannya dan Microsoft akan memberitahu FreeITSM sebaik sahaja sesuatu berubah, jadi ia sampai dalam beberapa saat. Ia mesti alamat <strong>HTTPS yang boleh dihubungi oleh Microsoft dari internet</strong>, berakhir dengan <code>/api/calendar/graph_notify.php</code>. Tugas berjadual masih diperlukan dalam kedua-dua keadaan: ia memperbaharui langganan, dan ia menangkap apa-apa yang akan hilang jika pemberitahuan terlepas.',
        'notify_suggest' => 'Guna alamat ini',
        'notify_suggest_note' => 'Diisikan daripada alamat yang sedang anda gunakan sekarang. Semak bahawa ia boleh dihubungi dari luar — di sebalik proksi atau terowong ia selalunya tidak boleh, dan yang salah gagal dengan mesej tentang pengesahan dan bukannya tentang alamat.',
        'notify_saved' => 'Tugas berjadual akan mencipta atau mengemas kini langganan pada larian seterusnya.',
        'notify_active' => '{n} langganan aktif',
        'health_checked' => 'Kalendar terakhir disemak {n} lalu.',
        'health_never' => 'Kalendar tidak pernah disemak.',
        'health_stale_note' => 'Perubahan yang dibuat dalam Outlook tiba apabila tugas berjadual dijalankan, jadi ini biasanya bermakna ia telah berhenti &mdash; semak bahawa <code>cron/calendar_sync_pull.php</code> masih berjalan mengikut jadualnya. Ia juga yang memperbaharui langganan, jadi pemberitahuan akan berhenti beberapa hari selepasnya. Jika anda sengaja menjalankannya kurang kerap daripada setiap setengah jam, ini adalah dijangka.',
