        'sub_expires' => 'Langganan diperbaharui dalam {n}',
        'sub_none' => 'Tidak melanggan',
        'sub_none_note' => 'Alamat pemberitahuan ditetapkan tetapi Microsoft tiada apa-apa untuk dipanggil bagi orang ini, jadi perubahan mereka hanya tiba apabila tugas berjadual dijalankan. Larian seterusnya akan cuba menciptanya; jika ia terus gagal, sebabnya akan dipaparkan di sini.',
        'sub_lapsed' => 'Langganan luput',
        'accept_deletes_note' => 'Mati secara lalai. Apabila dihidupkan, penganalisis yang memadam salah satu daripadanya pada telefon mereka akan mendapati tiket sudah tidak berjadual apabila mereka duduk &mdash; yang mana itu selalunya tujuannya. Setiap perubahan sedemikian ditulis ke dalam sejarah tiket, dan bilangan pemadaman yang luar biasa banyak dalam sekali gus akan ditolak dan bukannya dipatuhi, kerana itu lebih berkemungkinan satu kerosakan daripada satu arahan. Apabila dimatikan, temu janji yang dipadam hanya akan muncul semula pada kali seterusnya tiket berubah.',
        'feed_heading' => 'Pautan langganan',
        'feed_desc' => 'Penganalisis boleh menerbitkan kerja berjadual mereka sebagai pautan langganan kalendar, yang berfungsi dengan mana-mana aplikasi kalendar. Pautan adalah URL rahsia dan bukannya log masuk, jadi sesiapa sahaja yang memegangnya boleh membaca apa yang dipaparkannya.',
        'feed_label' => 'Benarkan pautan langganan',
        'feed_full' => 'Ya — termasuk subjek tiket',
        'feed_ref' => 'Ya — tetapi nombor tiket sahaja, tiada subjek',
        'feed_off' => 'Tidak',
        'feed_note' => 'Penganalisis sentiasa boleh memilih untuk menerbitkan kurang daripada ini, tidak pernah lebih. Mematikan ini serta-merta menghentikan pautan yang telah diberikan.',
