    'preferences' => [
        'ticket_workspace_heading' => 'Ruang kerja tiket',
        'ticket_workspace_label' => 'Guna ruang kerja',
        'ticket_workspace_desc' => 'Guna ruang kerja untuk tiket yang didayakan oleh pentadbir anda. Matikan untuk terus menggunakan anak tetingkap bacaan.',
        'live_heading' => 'Kemas kini langsung',
        'live_desc' => 'Kekerapan halaman menyemak perubahan yang dibuat oleh orang lain - senarai tiket, tiket yang dibuka, papan tugasan, loceng - dan mengejarnya. Ia dijeda semasa tab berada di latar belakang dan mengejar sebaik anda kembali. Berkuat kuasa dari halaman seterusnya yang anda buka.',
        'live_15' => 'Setiap 15 saat (lalai)',
