        'live_60' => 'Setiap minit',
        'live_0' => 'Mati - perubahan orang lain dipaparkan apabila anda memuat semula (mel baharu masih tiba)',
        'ticket_list_heading' => 'Senarai tiket',
        'ticket_list_desc' => 'Buka tiket sebagai senarai mesej atau sebagai barisan kerja berhalaman.',
        'ticket_list_messages' => 'Mesej',
        'ticket_list_table' => 'Jadual',
        'title' => 'Keutamaan',
        'subtitle' => 'Tetapan peribadi disimpan pada akaun anda — ia mengikut anda merentasi pelayar.',
        'tab_general' => 'Umum',
        'tab_notifications' => 'Pemberitahuan',
        'tab_display' => 'Paparan',
        'tab_details' => 'Butiran saya',
        'language_heading' => 'Bahasa antara muka',
        'language_desc' => 'Bahasa yang digunakan merentasi UI FreeITSM. Terjemahan kembali ke Bahasa Inggeris untuk mana-mana rentetan yang belum diliputi dalam bahasa pilihan anda. Memuat semula halaman apabila diubah.',
        'saving' => 'Menyimpan…',
        'notif_heading' => 'Dalam loceng',
        'notif_desc' => 'Yang manakah antara ini meletakkan sesuatu dalam loceng di bahagian atas skrin. Anda tidak pernah diberitahu tentang tindakan anda sendiri, dan beberapa perubahan pada tiket yang sama dikumpulkan menjadi satu.',
        'sound_heading' => 'Bunyi pemberitahuan',
        'sound_desc' => 'Mainkan bunyi pendek apabila sesuatu yang baharu tiba dalam loceng, atau apabila seseorang menyebut anda dalam War Room. Mati melainkan anda memilih bunyi.',
        'sound_off' => 'Tiada bunyi',
        'sound_chime' => 'Deringan',
        'sound_ping' => 'Ping',
        'sound_knock' => 'Ketukan',
        'sound_play' => 'Main',
        'sound_note' => 'Pelayar anda tidak akan memainkan bunyi sehingga anda mengklik di suatu tempat pada halaman, jadi pemberitahuan pertama selepas membuka tab mungkin senyap. Tiada apa-apa yang kedengaran untuk pemberitahuan yang sudah menunggu apabila anda membuka tab.',
        'cal_subtasks_heading' => 'Subtugasan pada kalendar tugasan',
        'cal_subtasks_desc' => 'Sama ada kalendar menunjukkan subtugasan bersama tugasan. Kalendar mempunyai kawalan yang sama dalam bar sisinya, dan kedua-duanya kekal selaras.',
        'task_view_heading' => 'Membuka tugasan',
        'task_view_desc' => 'Sama ada tugasan dibuka dalam panel di sebelah papan, atau dalam tetingkap besar dengan ruang untuk penerangan dan komen.',
        'task_view_panel' => 'Dalam panel sisi',
        'task_view_modal' => 'Dalam tetingkap besar',
        'task_open_other_desc' => 'Daripada Jadual, Kalendar dan Garis masa, tugasan dibuka dalam panel di sisi, supaya anda kekal di tempat anda. Pilih apa yang dipaparkan oleh panel itu.',
        'task_open_quick' => 'Pandangan sepintas lalu - status, tarikh, orang yang ditugaskan dan penerangan',
        'task_open_full' => 'Tugasan penuh - sama seperti pada papan, dengan subtugasan, senarai semak dan komen',
        'desktop_heading' => 'Pemberitahuan desktop',
        'desktop_desc' => 'Paparkan setiap pemberitahuan baharu daripada loceng sebagai pemberitahuan pada komputer anda - dalam Edge pada Windows, pemberitahuan Windows - supaya anda melihatnya walaupun sedang bekerja dalam tetingkap lain. FreeITSM perlu dibuka dalam tab pelayar agar ia tiba.',
        'desktop_label' => 'Paparkan pemberitahuan desktop',
        'desktop_test' => 'Uji',
        'desktop_test_title' => 'Pemberitahuan desktop dihidupkan',
        'desktop_test_body' => 'Pemberitahuan baharu daripada loceng akan muncul seperti ini.',
        'desktop_ask' => 'Pelayar anda akan bertanya sama ada mahu membenarkan pemberitahuan daripada laman ini apabila anda menghidupkannya.',
        'desktop_allowed' => 'Pelayar anda membenarkan pemberitahuan daripada laman ini.',
        'desktop_blocked' => 'Pelayar anda menyekat pemberitahuan daripada laman ini. Benarkannya dalam tetapan laman pelayar (mangga di sebelah alamat), kemudian hidupkan ini.',
        'desktop_unsupported' => 'Pelayar ini tidak dapat memaparkan pemberitahuan desktop.',
        'desktop_insecure' => 'Pelayar hanya membenarkan pemberitahuan desktop pada laman yang dibuka melalui https.',
        'task_email_heading' => 'Tugasan yang ditugaskan kepada anda',
        'task_email_desc' => 'Dapatkan e-mel setiap kali tugasan ditugaskan kepada anda - apabila satu dicipta untuk anda, atau diserahkan kepada anda daripada orang lain. Tiada apa dihantar untuk tugasan yang anda tugaskan kepada diri sendiri.',
        'task_email_label' => 'E-melkan saya apabila tugasan ditugaskan kepada saya',
        'board_subtasks_heading' => 'Subtugasan pada papan tugasan',
        'board_subtasks_desc' => 'Tugasan yang mempunyai subtugasan menyenaraikannya di bawah kadnya pada papan. Pilih yang mana - kad sentiasa memaparkan bilangannya, dan mengklik bilangan itu menunjukkan atau menyembunyikan senarai kad itu sahaja. Pilihan yang sama ada dalam bar sisi Tugasan.',
        'board_subtasks_label' => 'Sembunyikan setelah semuanya selesai',
        'board_subtasks_all' => 'Semua subtugasan',
        'board_subtasks_open' => 'Hanya yang masih perlu dilakukan',
        'board_subtasks_none' => 'Tiada - bilangan sahaja',
        'work_fold_heading' => 'Seksyen kerja kosong pada tugasan',
        'work_fold_desc' => 'Paparan Kerja sesuatu tugasan mempunyai Senarai semak, Borang, Prosedur dan Susulan. Pilih sama ada yang tiada apa-apa di dalamnya dipaparkan sepenuhnya, dengan kawalan lampir dan ciptanya, atau dilipat menjadi tajuk seperti "Senarai semak (0)" yang dibuka dengan satu klik.',
        'work_fold_show' => 'Paparkan sepenuhnya',
        'work_fold_collapse' => 'Lipat yang kosong menjadi tajuk',
        'nt_company_heading' => 'Syarikat saya untuk tiket baharu',
        'nt_company_desc' => 'Dalam paparan semua syarikat, Tiket baharu bertanya syarikat mana tiket itu untuk. Pilih satu di sini untuk memilihnya bagi pihak anda. Anda masih boleh mengubahnya pada borang, dan jika anda tidak lagi dapat mencapai syarikat itu, tiada apa-apa dipilih.',
        'nt_company_none' => 'Tiada - saya memilih setiap kali',
        'search_dismiss_heading' => 'Menutup panel carian',
        'search_dismiss_desc' => 'Panel carian boleh diseret ke tepi dan dibiarkan terbuka, jadi secara lalai hanya ✕ atau kekunci Escape yang menutupnya. Hidupkan ini supaya ia tertutup sebaik sahaja anda mengklik di tempat lain — pada senarai folder, senarai tiket atau bar alat. Mengklik tiket yang baru anda jumpai, atau sifat-sifatnya, masih membiarkan panel terbuka, jadi carian terus wujud walaupun anda bertindak ke atas hasilnya.',
        'search_dismiss_label' => 'Tutup apabila saya mengklik di tempat lain',
        'section_memory_heading' => 'Kembali ke sesuatu modul',
        'section_memory_desc' => 'Apabila anda membuka modul daripada menu, laman utama atau Ctrl+K, kembali ke seksyen yang terakhir anda gunakan di sana - Assets → Servers, misalnya - dan bukannya halaman depannya. Pautan ke halaman atau rekod tertentu masih membuka tepat itu. Diingati dalam pelayar ini.',
        'section_memory_label' => 'Buka semula seksyen terakhir setiap modul',
        'remember_company_heading' => 'Syarikat semasa log masuk',
        'remember_company_desc' => 'Mulakan setiap log masuk dalam syarikat yang terakhir anda pilih dalam penukar syarikat (atau dalam Semua syarikat), dan bukannya syarikat Lalai. Syarikat yang tidak lagi dapat anda lihat, atau yang telah dinyahaktifkan, dilangkau. Tiket baharu difailkan kepada syarikat yang anda sedang bekerja di dalamnya, jadi semak penukar sebelum anda mencipta satu.',
        'remember_company_label' => 'Mulakan dalam syarikat yang terakhir saya gunakan',
        'landing_heading' => 'Halaman permulaan',
        'workcal_heading' => 'Kalendar kerja saya',
        'taskcal_heading' => 'Tugasan dalam kalendar ini',
        'taskcal_off' => 'Tiada',
        'taskcal_work' => 'Bila saya merancang untuk melakukannya',
        'taskcal_due' => 'Bila ia perlu disiapkan',
        'taskcal_both' => 'Kedua-duanya',
        'taskcal_note' => 'Tugasan boleh meletakkan dua perkara dalam kalendar anda: slot yang anda sisihkan untuk melakukannya, sebagai temu janji biasa, dan tarikh akhirnya, sebagai entri sepanjang hari. Tugasan yang selesai dibuang, dan tugasan yang ditugaskan kepada pasukan dan bukannya kepada anda tidak akan pernah ditambah.',
        'taskcal_failed' => 'Pilihan itu tidak dapat disimpan',
        'workcal_desc' => 'Masukkan tiket yang telah anda jadualkan ke dalam kalendar yang benar-benar anda gunakan — Google, Apple, Outlook atau apa-apa sahaja lain yang boleh melanggan kalendar.',
