        'workcal_push_bad' => 'Tiada kalendar dapat ditemui untuk {addr}. Itu ialah alamat pada akaun FreeITSM anda, dan ia tidak selalunya peti mel anda — minta pentadbir menghalakan penyegerakan kalendar anda kepada yang betul.',
        'workcal_push_noaddr' => 'Kami tidak tahu peti mel mana yang milik anda. Minta pentadbir menetapkannya pada Sistem → Penyegerakan kalendar.',
