        'workcal_insecure' => 'Sistem ini tidak menggunakan HTTPS, jadi pautan ini — dan segala yang dipaparkannya — bergerak merentasi rangkaian tanpa perlindungan setiap kali kalendar anda dimuat semula. Minta pentadbir anda mendayakan HTTPS sebelum menggunakannya di luar rangkaian yang dipercayai.',
