        'modorder_heading' => 'Susunan modul',
        'modorder_desc' => 'Susunan modul dalam menu waffle anda, pada halaman utama dan dalam senarai "Go to" Ctrl+K. Seret modul pada pemegangnya, gunakan anak panah, atau pilih satu dan tekan Alt dengan anak panah atas atau bawah. Hanya anda yang melihat susunan ini.',
        'modorder_note' => 'Disimpan semasa anda melakukannya, dan digunakan mulai halaman seterusnya yang anda buka. Modul yang ditambah dalam kemas kini kemudian menyertai senarai dengan sendirinya.',
