        'panels_narrow' => 'Dalam tetingkap selebar 1100px atau kurang, folder Tiket bermula sebagai jalur walaupun pada Sentiasa kelihatan, supaya tiket yang anda baca mempunyai ruang. Ia kembali apabila tetingkap lebih lebar.',
