        'multiselect_desc' => 'Dalam peti masuk tiket anda boleh memilih beberapa tiket sekali gus — Ctrl+klik untuk memilih satu demi satu, Shift+klik untuk blok. Ini menentukan apa yang dipaparkan skrin semasa lebih daripada satu dipilih.',
        'multiselect_summary' => 'Panel ringkasan',
