    'currencies' => [
        'title' => 'Mata Wang',
        'subtitle' => 'Setiap mata wang yang digunakan di dunia tersedia di mana-mana FreeITSM merekodkan wang. Pilih yang mana diutamakan, yang mana menjadi permulaan bagi rekod baharu, dan cara jumlah ditulis. Mana-mana penganalisis boleh memilih format yang berbeza untuk diri sendiri dalam Keutamaan.',
        'fav_heading' => 'Kegemaran',
