    'security' => [
        'title' => 'Keselamatan',
        'subtitle' => 'Konfigurasikan polisi pengesahan dan perlindungan akaun',
        'selfreg_heading' => 'Pendaftaran layan diri',
        'selfreg_desc' => 'Sama ada orang boleh mencipta akaun portal layan diri mereka sendiri daripada halaman log masuk. Mati secara lalai. Apabila dihidupkan, pendaftaran masih disahkan melalui pautan e-mel sebelum mana-mana kata laluan ditetapkan.',
        'selfreg_label' => 'Benarkan pendaftaran sendiri',
        'selfreg_hint' => 'Mati = tiada sesiapa boleh mencipta akaun sendiri. Orang yang anda tambah masih boleh log masuk – mereka menetapkan kata laluan pertama melalui “Lupa kata laluan anda?” di halaman log masuk portal.',
        'trusted_heading' => 'Peranti Dipercayai',
        'trusted_desc' => 'Benarkan pengguna melangkau pengesahan OTP pada pelayar yang dipercayai. Pengguna menyertai secara individu melalui menu avatar mereka. Tetapkan kepada 0 untuk melumpuhkan ciri ini sepenuhnya.',
        'trust_duration' => 'Tempoh kepercayaan',
        'trust_duration_hint' => 'Berapa lama peranti kekal dipercayai selepas pengesahan OTP',
        'password_heading' => 'Polisi Kata Laluan',
        'password_desc' => 'Wajibkan pengguna menukar kata laluan mereka secara berkala. Apabila kata laluan tamat tempoh, pengguna diarahkan ke skrin tukar kata laluan wajib pada log masuk seterusnya. Tetapkan kepada 0 untuk melumpuhkan.',
        'password_expiry' => 'Tamat tempoh kata laluan',
        'password_expiry_hint' => 'Usia maksimum kata laluan sebelum ia mesti ditukar',
        'lockout_heading' => 'Kunci Akaun',
        'lockout_desc' => 'Kunci akaun selepas percubaan log masuk gagal berulang untuk mengelakkan serangan brute-force. Tetapkan percubaan maksimum kepada 0 untuk melumpuhkan kunci.',
        'max_attempts' => 'Percubaan gagal maksimum',
        'max_attempts_hint' => 'Bilangan kata laluan salah sebelum akaun dikunci',
        'lockout_duration' => 'Tempoh kunci',
        'lockout_duration_hint' => 'Berapa lama akaun kekal dikunci (kaunter set semula selepas dibuka)',
        'ipban_heading' => 'Sekatan IP',
        'ipban_desc' => 'Sekat secara automatik alamat IP yang cuba log masuk berulang kali terhadap akaun yang tidak wujud atau dikunci. Setiap sekatan berlangsung 24 jam. Selepas setiap sekatan, ambang berkurang 1 (sehingga minimum), menyukarkan penyalah guna berulang. Tetapkan percubaan maksimum kepada 0 untuk melumpuhkan.',
        'first_ban' => 'Ambang sekatan pertama',
        'first_ban_hint' => 'Percubaan gagal sebelum IP disekat buat kali pertama',
        'min_threshold' => 'Ambang minimum',
        'min_threshold_hint' => 'Ambang berhenti berkurang sebaik sahaja ia mencapai lantai ini',
        'ipban_example_strong' => 'Contoh:',
        'ipban_example_text' => 'Dengan maksimum 5 dan minimum 2, sekatan pertama tercetus selepas 5 percubaan gagal, kedua selepas 4, kemudian 3, kemudian 2. Ia kekal pada 2 untuk setiap sekatan berikutnya. Hanya percubaan terhadap nama pengguna yang tidak wujud atau akaun yang sudah dikunci dikira.',
        'attachments_heading' => 'Lampiran',
        'attachments_desc' => 'FreeITSM hanya menerima jenis lampiran yang dikenalinya. Apa-apa yang lain — sebuah program, skrip, halaman web — tidak akan pernah disimpan dengan nama sendiri, jadi ia tidak boleh dijalankan.',
        'rejected_behaviour' => 'Apabila jenis fail tidak diterima',
        'rejected_behaviour_hint' => 'Terpakai kepada e-mel, portal, dan saluran sembang.',
        'rejected_store' => 'Simpan, muat turun sahaja',
        'rejected_drop' => 'Jangan simpan',
        'allowed_extensions' => 'Jenis fail diterima',
        'allowed_extensions_hint' => 'Biarkan kosong untuk menerima semua yang dianggap selamat oleh FreeITSM, termasuk jenis baharu yang ditambah oleh kemas kini akan datang. Untuk menerima kurang, senaraikan hanya sambungan yang anda mahukan, dipisahkan dengan koma.',
        'allowed_extensions_ph' => 'cth. pdf, docx, xlsx, png, jpg',
        'allowed_extensions_note' => 'Anda hanya boleh menyempitkan senarai ini. Sambungan yang tidak dianggap selamat oleh FreeITSM akan diabaikan, jadi tiada apa yang ditaip di sini boleh menjadikan program atau skrip boleh diterima.',
        'rejected_note' => 'Dalam kedua-dua keadaan tiket menyatakan apa yang berlaku dan mengapa, jadi tiada sesiapa perlu tertanya-tanya ke mana fail mereka pergi.',
        'max_attachment' => 'Lampiran terbesar',
        'max_attachment_hint' => 'Tiada satu lampiran pun boleh lebih besar daripada ini - dalam e-mel, portal, saluran sembang, balasan dan dokumen yang dilampirkan. 10 MB melainkan anda mengubahnya.',
        'max_total' => 'E-mel terbesar',
        'max_total_hint' => 'Semua lampiran pada satu e-mel masuk digabungkan. 0 bermaksud tiada had selain yang di atas.',
        'php_limits' => 'PHP pada pelayan ini menerima muat naik pelayar sehingga {upload} bagi setiap fail dan {post} bagi setiap permintaan (upload_max_filesize dan post_max_size dalam php.ini), dan mempunyai {memory} memori untuk digunakan. Fail yang ditolak PHP tidak pernah sampai ke FreeITSM, jadi had yang melebihi ini hanya membantu e-mel. Pelayan web atau proksi di hadapan (nginx client_max_body_size, IIS maxAllowedContentLength) boleh menetapkan had lebih rendah tersendiri.',
        'php_limits_warn' => 'Lampiran terbesar lebih tinggi daripada yang diterima PHP daripada pelayar: naikkan upload_max_filesize dan post_max_size dalam php.ini juga, atau fail yang dimuat naik melalui FreeITSM akan ditolak sebelum sampai.',
        'php_unlimited' => 'tiada had',
        'oversize_signpost' => 'Apa yang berlaku kepada e-mel masuk yang melebihi had ini - menolaknya, atau menyimpannya tanpa lampiran yang terlalu besar, dan siapa yang dimaklumkan - ditetapkan dalam {link}. Setiap peti mel juga boleh menetapkan had tersendiri di sana.',
        'oversize_signpost_link' => 'Tiket -> Tetapan -> Peti mel',
