        'never_explain' => '<strong>Webhook tidak akan dihantar</strong> sehingga pekerja penghantaran latar belakang dijadualkan untuk berjalan.',
        'down_explain' => '<strong>Webhook tidak lagi dihantar</strong> &mdash; pekerja kali terakhir berjalan {when} dan nampaknya telah berhenti.',
        'stale_explain' => 'Pekerja sedang berjalan tetapi ketinggalan jadual (larian terakhir {when}). Ia sepatutnya berjalan setiap minit.',
        'queued_one' => '<strong>1</strong> webhook berada dalam baris gilir dan menunggu.',
        'queued_many' => '<strong>{n}</strong> webhook berada dalam baris gilir dan menunggu.',
        'step1' => '<strong>Jadualkan pekerja penghantaran supaya berjalan setiap minit.</strong> Pada pelayan, jalankan arahan ini daripada tugas berjadual (Windows Task Scheduler) atau cron (Linux):',
        'step1_http' => 'Tidak boleh menjalankan PHP daripada shell? Panggil ia melalui HTTP sebaliknya (cth. daripada perkhidmatan cron yang dihoskan):',
        'step2' => '<strong>Tambah tindakan <em>Hantar webhook</em> ke sesuatu aliran kerja</strong> supaya peristiwa mula mengisi baris gilir &mdash; di bawah <a href="{url}">Aliran Kerja</a>.',
        'step3' => '<strong>Perhatikan halaman ini.</strong> Sebaik sahaja pekerja berjalan, status di atas bertukar hijau dan penghantaran muncul di bawah. Nota persediaan penuh (Windows &amp; Linux, pengesahan tandatangan) ada dalam <a href="https://github.com/edmozley/freeitsm/wiki/Workflows" target="_blank" rel="noopener">wiki Workflows</a>.',
        'fact_worker' => 'Skrip pekerja',
        'fact_retry' => 'Jadual cuba semula',
        'fact_retry_sched' => '{schedule} &middot; mati selepas {n} percubaan',
        'fact_retry_once' => 'Tiada percubaan semula &middot; mati selepas 1 percubaan',
        'fact_retention' => 'Pengekalan log',
        'fact_queued' => 'Dalam baris gilir kini',
        'days' => '{n} hari',
        'del_title' => 'Penghantaran',
        'del_desc' => 'Sejauh mana FreeITSM berusaha menyampaikan setiap webhook.',
        'opt_default' => '{label} (lalai)',
        'del_attempts_label' => 'Percubaan sebelum berhenti',
        'del_attempts_one' => '1 percubaan (tiada percubaan semula)',
        'del_attempts_opt' => '{n} percubaan',
        'del_attempts_help' => 'Percubaan yang gagal dicuba semula selepas 1 minit, kemudian 5 minit, 15 minit, 1 jam dan 6 jam, kemudian setiap 6 jam. Selepas percubaan terakhir, penghantaran ditandakan <strong>Mati</strong> dan menunggu <em>Main semula</em>. Perubahan digunakan untuk webhook yang diletakkan dalam baris gilir mulai sekarang - yang sudah dalam baris gilir mengekalkan bilangan yang dimulakannya.',
        'del_timeout_label' => 'Tunggu endpoint menjawab',
        'del_timeout_opt' => '{n} saat',
        'del_timeout_help' => 'Berapa lama setiap percubaan menunggu sebelum dikira gagal. Tinggikannya hanya untuk endpoint yang diketahui perlahan: pekerja menghantar satu webhook pada satu masa, jadi penantian yang lama menahan baki baris gilir. <em>Hantar ujian</em> dalam editor workflow menunggu paling lama 25 saat.',
        'del_int_label' => 'Jika penghantaran terputus separuh jalan',
        'del_int_retry' => 'Cuba lagi - endpoint mungkin menerimanya dua kali',
        'del_int_stop' => 'Henti, dan biarkan untuk Main semula',
        'del_int_help' => 'Jika pekerja dihentikan di tengah penghantaran - pelayan dimulakan semula, atau tugas berjadual dimatikan - tiada siapa tahu sama ada endpoint menerimanya. Selepas 10 minit FreeITSM menyelesaikannya: <strong>Cuba lagi</strong> mengira ia sebagai percubaan yang gagal dan mencuba semula mengikut jadual di atas; <strong>Henti</strong> menandakannya Mati serta-merta, supaya anda boleh menyemak endpoint dan Main semula sendiri. Setiap penghantaran membawa pengepala <code>X-FreeITSM-Delivery</code> dengan nombor yang sama pada setiap percubaan dan pada Main semula, jadi penerima yang anda jalankan sendiri boleh mengabaikan pengulangan. Alat sembang seperti Slack dan Teams tidak boleh, dan akan menunjukkan mesej dua kali.',
        'dp_title' => 'Perlindungan data',
        'dp_desc' => 'Apa yang FreeITSM simpan pada cakera tentang webhook anda, dan untuk berapa lama.',
        'enc_on_title' => 'URL webhook dan rahsia penandatanganan disulitkan semasa disimpan',
        'enc_on_body' => 'Disimpan dengan AES-256-GCM, dalam aliran kerja dan dalam baris gilir penghantaran. URL webhook itu sendiri ialah kelayakan &mdash; sesiapa yang memilikinya boleh menghantar ke saluran anda &mdash; dan rahsia penandatanganan ialah bukti bahawa mesej benar-benar datang daripada anda.',
        'enc_off_title' => 'Tiada kunci penyulitan dikonfigurasikan &mdash; URL webhook dan rahsia penandatanganan disimpan dalam teks biasa',
        'enc_off_body' => 'FreeITSM menyulitkan nilai ini apabila fail kunci penyulitan ada, tetapi pemasangan ini tidak mempunyainya, jadi ia disimpan sebagaimana adanya dan bukannya menggagalkan webhook anda terus. Sesiapa yang boleh membaca pangkalan data atau sandarannya boleh menghantar ke saluran anda dan memalsukan tandatangan anda. Konfigurasikan kunci penyulitan (<code>ENCRYPTION_KEY_PATH</code>) dan simpan semula setiap aliran kerja webhook untuk menyulitkan nilai yang disimpan.',
        'ret_label' => 'Simpan muatan yang dihantar selama',
        'ret_none' => 'Jangan simpan langsung',
        'ret_1' => '1 hari',
        'ret_7' => '7 hari (disyorkan)',
        'ret_30' => '30 hari',
        'ret_forever' => 'Selagi rekod penghantaran wujud',
        'ret_help' => 'Log penghantaran menyimpan muatan tepat yang telah dihantar. Dengan format <strong>Rekod penuh</strong>, itu ialah <strong>keseluruhan tiket</strong> &mdash; subjek, pemohon, semuanya &mdash; disalin ke sini dalam teks biasa. Selepas bilangan hari ini, muatan dan badan respons dibersihkan, manakala <em>rekod</em> penghantaran (endpoint, status, masa, ralat) dikekalkan untuk audit sehingga pengekalan log di atas ({days} hari) membuang baris itu sepenuhnya.',
        'ret_tradeoff' => '<strong>Timbal balik:</strong> <em>Main semula</em> menghantar semula muatan yang disimpan, jadi penghantaran yang muatannya telah dibersihkan tidak boleh dimainkan semula lagi. Main semula lazimnya digunakan dalam beberapa jam selepas kegagalan, bukan beberapa minggu.',
        'ov_title' => 'Gambaran keseluruhan',
