    'managers' => [
        'heading' => 'Pengurus',
        'intro' => 'Pengurus ialah seseorang dalam portal layan diri yang boleh melihat tiket yang dibuka oleh orang yang diuruskannya - contohnya ketua jabatan. Mereka mendapat tab <strong>Tiket pasukan</strong> dalam portal. Meja perkhidmatan tidak terjejas.',
        'needs_verify' => 'Jalankan Sistem → Pengesahan Pangkalan Data dahulu. Sehingga ia dijalankan, pengurus kekal dimatikan apa pun yang ditetapkan di sini, kerana tiket sulit tidak dapat dibezakan.',
        'on_heading' => 'Pengurus dalam portal',
        'enabled' => 'Benarkan pengurus melihat tiket pasukan mereka',
        'enabled_desc' => 'Mati sehingga anda menghidupkannya. Tiada apa di bawah mempunyai kesan selagi ini dimatikan.',
        'source_heading' => 'Dari mana pengurus datang',
        'source_desc' => 'Dua sumber, kedua-duanya serentak. Barisan pengurusan disediakan bagi setiap pengurus dengan butang Akses pengurus pada Tiket → Pengguna atau Aset → Pengguna.',
        'directory' => 'Gunakan medan Pengurus setiap orang',
        'directory_desc' => 'Sesiapa yang ditetapkan sebagai Pengurus seseorang - secara manual, atau daripada direktori anda - boleh melihat tiket mereka.',
        'depth' => 'Sejauh mana ke bawah',
        'depth_direct' => 'Orang yang melapor terus kepada mereka',
        'depth_all' => 'Semua orang di bawah mereka, sehingga ke bawah sekali',
        'can_heading' => 'Apa yang boleh dilakukan pengurus',
        'can_desc' => 'Pengurus sentiasa boleh membaca tiket pasukan mereka. Mereka dimaklumkan pada setiap tiket tentang apa lagi yang dibenarkan.',
        'can_reply' => 'Membalas tiket pasukan mereka',
        'can_close' => 'Menutup tiket pasukan mereka',
        'conf_heading' => 'Tiket sulit',
        'conf_desc' => 'Apa yang dilihat pengurus tentang tiket yang ditandakan sulit - diagnosis yang dihantar kepada HR, atau aduan tentang pengurus itu sendiri.',
        'conf_none' => 'Tiada apa-apa langsung (disyorkan)',
        'conf_none_desc' => 'Tiket ditinggalkan sepenuhnya. Pengurus tidak dapat mengetahui pun ia wujud.',
        'conf_stub' => 'Bahawa tiket sulit wujud',
        'conf_stub_desc' => 'Disenaraikan sebagai "Tiket sulit" dengan nombor dan statusnya, tanpa apa yang dikatakannya. Sedarlah bahawa ini sahaja boleh memberitahu pengurus bahawa seseorang membuka sesuatu yang peribadi.',
        'conf_all' => 'Semuanya',
        'conf_all_desc' => 'Tiket sulit dipaparkan seperti yang lain. Pilih ini hanya jika tiada apa yang sulit pernah dibuka melalui portal ini.',
        'notify_heading' => 'Memaklumkan pengurus tentang tiket baharu',
        'notify_desc' => 'Apabila seseorang dalam pasukan pengurus membuka tiket - tetapi tidak pernah yang tidak boleh dibuka oleh pengurus, seperti tiket sulit.',
        'notify_none' => 'Jangan maklumkan (lalai)',
        'notify_none_desc' => 'Pengurus melihat tiket baharu apabila mereka melihat Tiket pasukan.',
        'notify_email' => 'E-melkan mereka',
        'notify_email_desc' => 'E-mel dengan nombor dan subjek tiket serta pautan kepadanya, dihantar ke alamat pengurus daripada peti mel tiket. Pengurus tanpa alamat tidak mendapat apa-apa. Pautan memerlukan alamat web awam (Tiket → Tetapan → Templat E-mel) - tanpanya, tiket yang tiba melalui e-mel menghantar pautan yang tidak berfungsi.',
        'notify_bell' => 'Dalam loceng pemberitahuan portal',
        'notify_bell_desc' => 'Ke dalam loceng yang dimiliki setiap pengurus pada pengepala portal - loceng yang sama dengan penganalisis. Lebih senyap daripada e-mel: ia ada apabila mereka log masuk seterusnya.',
        'leavers_heading' => 'Orang yang telah berhenti',
        'leavers' => 'Terus paparkan tiket orang yang telah berhenti',
        'leavers_desc' => 'Dihidupkan secara lalai, supaya tiket yang masih terbuka apabila seseorang berhenti kekal diawasi. Pengurus yang telah berhenti sentiasa kehilangan akses.',
        'edit_heading' => 'Siapa boleh menyediakan barisan pengurusan',
        'edit_admins' => 'Pentadbir sahaja',
