    'self_service' => [
        'heading' => 'Portal layan diri',
        'intro' => 'Bagaimana portal kelihatan kepada orang yang membuka tiket, dan apa yang boleh mereka lakukan di sana. Bagi kebanyakan organisasi, portal ialah satu-satunya bahagian FreeITSM yang dilihat oleh pelanggan, jadi ia satu-satunya skrin yang berbaloi dijenamakan berasingan daripada yang lain.',
        'appearance_heading' => 'Rupa',
        'appearance_desc' => 'Ini terpakai untuk portal sahaja. Logo di bawah <strong>Sistem &rarr; Penjenamaan</strong> masih meliputi aplikasi, skrin log masuk dan e-mel anda.',
        'logo_label' => 'Logo portal',
        'logo_desc' => 'Logo yang berbeza untuk portal &mdash; berguna apabila meja bantuan berniaga di bawah nama lain, atau apabila logo utama direka untuk pengepala aplikasi yang gelap dan kelihatan janggal pada halaman cerah. Biarkan kosong untuk menggunakan logo utama.',
        'logo_remove' => 'Buang',
        'logo_hint' => 'PNG atau JPG, sehingga 2MB. SVG tidak diterima: ia ialah XML yang boleh membawa skrip, dan imej ini dihidangkan kepada semua orang yang melawat portal.',
        'logo_saved' => 'Logo portal dikemas kini',
        'logo_position_label' => 'Kedudukan logo',
        'logo_position_desc' => 'Dalam bar, ia berada di sebelah nama portal, kecil dan sentiasa kelihatan pada skrin. Pada halaman, ia muncul sekali di bahagian atas, lebih besar, pada latar belakang halaman &mdash; dan bar kemudian hanya menunjukkan nama portal dan tidak mengulanginya.',
        'logo_position_header' => 'Dalam bar atas',
        'logo_position_page' => 'Di bahagian atas halaman',
        'header_colour_label' => 'Warna bar pengepala',
        'header_colour_desc' => 'Bar di bahagian atas setiap halaman portal. Biarkan kosong untuk mengikut tema warna.',
        'table_colour_label' => 'Warna pengepala jadual',
        'table_colour_desc' => 'Baris tajuk bagi senarai tiket dan aset. Biarkan kosong untuk mengikut tema warna.',
        'use_theme' => 'Guna tema',
        'pattern_label' => 'Latar belakang',
        'pattern_desc' => 'Corak halus di belakang halaman. Dilukis dengan CSS dan bukan imej, serta diwarnakan daripada tema, jadi ia kekal mudah dibaca dalam mod cerah mahupun gelap.',
        'pattern_none' => 'Tiada',
        'pattern_dots' => 'Bintik',
        'pattern_grid' => 'Grid',
        'pattern_diagonal' => 'Serong',
        'pattern_flow' => 'Aliran',
        'pattern_mesh' => 'Jaringan',
        'preview_heading' => 'Pratonton',
        'preview_desc' => 'Apa yang dilihat oleh pelanggan. Dikemas kini semasa anda mengubah tetapan di atas; tiada apa-apa disimpan sehingga anda menekan Simpan.',
        'preview_portal' => 'Portal sokongan',
        'preview_col_ref' => 'Rujukan',
        'preview_col_subject' => 'Subjek',
        'preview_row' => 'Komputer riba tidak mahu hidup',
        'behaviour_heading' => 'Apa yang portal benarkan orang lakukan',
        'behaviour_desc' => 'Semua ini mati pada mulanya, jadi portal sedia ada berfungsi sama seperti sebelum tetapan ini wujud.',
        'self_close_label' => 'Benarkan orang menutup tiket mereka sendiri',
        'self_close_desc' => 'Menambah butang <strong>Tidak diperlukan lagi</strong> pada tiket di dalam portal. Tiket ditutup dengan nota yang menyatakan bahawa pemohon menutupnya, jadi jejaknya menunjukkan siapa yang melakukannya dan bukannya penganalisis yang kelihatan seolah-olah menyelesaikan sesuatu yang tidak pernah disentuhnya. Mereka tidak boleh menutup tiket yang sedang dikerjakan orang lain jika ia telah diselesaikan sambil menunggu pengesahan mereka &mdash; yang itu memang untuk mereka sahkan.',
